def compute(vars):
    old_value = vars["v2"]
    new_value = vars["v1"]
    if old_value == 0:
        return None

    change_ratio = (new_value - old_value) / old_value
    percentage_change = change_ratio * 100

    return {
        "value": percentage_change,
        "trace": {
            "old_value_2007": old_value,
            "new_value_2005": new_value,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
